(function(){
'use strict';
if(window.__cpaMobileNavViews)return; window.__cpaMobileNavViews=true;
var css=`
#cpa-mobile-bar{display:none}#cpa-page-views{font:600 13px/1.4 system-ui,-apple-system,sans-serif;color:#52646b;background:rgba(247,250,248,.9);border:1px solid rgba(82,100,107,.16);border-radius:999px;padding:7px 12px;width:max-content;max-width:calc(100% - 32px);margin:14px auto 20px;box-shadow:0 3px 12px rgba(35,55,60,.06)}
@media(max-width:820px){body{padding-top:58px!important}#cpa-mobile-bar{display:flex!important;position:fixed;z-index:2147483000;left:0;right:0;top:0;height:58px;align-items:center;gap:10px;padding:0 12px;background:rgba(249,247,241,.97);backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border-bottom:1px solid rgba(65,83,80,.16);box-shadow:0 3px 18px rgba(28,45,43,.1)}#cpa-mobile-bar .brand{font:800 17px/1.1 system-ui,-apple-system,sans-serif;color:#253c3a;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1;text-decoration:none}#cpa-mobile-bar button{width:42px;height:42px;border:0;border-radius:12px;background:rgba(85,112,105,.1);color:#294642;font-size:25px;line-height:1;display:grid;place-items:center}#cpa-mobile-menu{position:fixed;z-index:2147482999;top:58px;left:0;right:0;max-height:calc(100dvh - 58px);overflow-y:auto;overscroll-behavior:contain;background:rgba(249,247,241,.985);padding:12px 16px 28px;border-bottom:1px solid rgba(65,83,80,.16);box-shadow:0 14px 28px rgba(28,45,43,.15);display:none}#cpa-mobile-menu.open{display:block}#cpa-mobile-menu a{display:block;padding:13px 10px;border-bottom:1px solid rgba(65,83,80,.11);font:700 16px/1.35 system-ui,-apple-system,sans-serif;color:#294642;text-decoration:none}#cpa-mobile-menu .langs{display:flex;gap:8px;flex-wrap:wrap;padding:14px 6px}#cpa-mobile-menu .langs button{border:1px solid rgba(65,83,80,.2);border-radius:999px;background:#fff;padding:8px 11px;color:#294642;font-weight:700}.site-header nav,.site-nav,.main-nav header nav{max-width:100%}}
`;
var st=document.createElement('style');st.textContent=css;document.head.appendChild(st);
function base(){var p=location.pathname.split('/').filter(Boolean);return p.length?'/'+p[0]+'/':'/';}
function addNav(){if(document.getElementById('cpa-mobile-bar'))return;var root=base();var bar=document.createElement('div');bar.id='cpa-mobile-bar';bar.innerHTML='<button type="button" aria-label="開啟選單" aria-expanded="false">☰</button><a class="brand" href="'+root+'">護童行動聯盟</a><button type="button" class="lang" aria-label="語言">文</button>';var menu=document.createElement('div');menu.id='cpa-mobile-menu';var links=[['首頁',''],['關於我們','about/'],['法院紀錄','court-records/'],['旁聽紀錄','hearing-records/'],['案件追蹤','cases/'],['活動紀錄','activities/'],['法庭漫畫','court-comics/'],['特別專題','special-topics/'],['官方社群','social/'],['全球守護留言牆','https://cn.globalprotectionwall.com/']];menu.innerHTML=links.map(function(x){return '<a href="'+(x[1].indexOf('http')===0?x[1]:root+x[1])+'">'+x[0]+'</a>';}).join('')+'<div class="langs"><button data-cpa-lang="zh-Hant">繁</button><button data-cpa-lang="zh-Hans">简</button><button data-cpa-lang="en">EN</button><button data-cpa-lang="ja">日</button></div>';document.body.appendChild(bar);document.body.appendChild(menu);var toggle=bar.querySelector('button');function close(){menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.textContent='☰';}toggle.onclick=function(){var o=menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(o));toggle.textContent=o?'×':'☰';};bar.querySelector('.lang').onclick=function(){menu.classList.add('open');toggle.setAttribute('aria-expanded','true');toggle.textContent='×';menu.scrollTop=menu.scrollHeight;};menu.addEventListener('click',function(e){var b=e.target.closest('[data-cpa-lang]');if(b){try{localStorage.setItem('site-lang',b.dataset.cpaLang);}catch(_){};document.documentElement.lang=b.dataset.cpaLang;document.dispatchEvent(new CustomEvent('cpa-language-change',{detail:{lang:b.dataset.cpaLang}}));close();}});document.addEventListener('keydown',function(e){if(e.key==='Escape')close();});}
function pageKey(){var p=location.pathname.replace(/\/(index\.html)?$/,'/');return 'cpa_views_'+p.replace(/[^a-zA-Z0-9\u4e00-\u9fff]+/g,'_');}
function addViews(){if(document.getElementById('cpa-page-views'))return;var key=pageKey(),seen=key+'_seen',n=0;try{n=parseInt(localStorage.getItem(key)||'0',10)||0;if(!sessionStorage.getItem(seen)){n++;localStorage.setItem(key,String(n));sessionStorage.setItem(seen,'1');}}catch(_){n=1;}var el=document.createElement('div');el.id='cpa-page-views';el.setAttribute('role','status');el.textContent='◉ 本裝置累計瀏覽 '+n.toLocaleString()+' 次';var target=document.querySelector('main h1, article h1, .hero h1, h1');if(target){var host=target.closest('header,.hero,.article-header')||target.parentElement;host.insertAdjacentElement('afterend',el);}else{var main=document.querySelector('main')||document.body;main.insertBefore(el,main.firstChild);} }
function init(){addNav();addViews();}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();